<?php
namespace App\Http\Controllers;
use App\Models\{Order,Product,Customer};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
class OrderController extends Controller {
 private function mid():int{return (int)auth()->user()->mype_id ?: abort(403);}
 public function index(){ $id=$this->mid();return view('orders.index',['orders'=>Order::where('mype_id',$id)->with(['customer','items'])->latest()->paginate(15),'customers'=>Customer::where('mype_id',$id)->orderBy('name')->get(),'products'=>Product::where('mype_id',$id)->where('active',1)->orderBy('name')->get(),'pending'=>Order::where('mype_id',$id)->where('status','pending')->count()]);}
 public function store(Request $request){$id=$this->mid();$data=$request->validate(['customer_id'=>['nullable','integer',Rule::exists('customers','id')->where('mype_id',$id)],'payment_method'=>'nullable|string|max:50','notes'=>'nullable|string|max:2000','items'=>'required|array|min:1','items.*.product_id'=>'required|integer','items.*.quantity'=>'required|integer|min:1|max:100000']);
 DB::transaction(function()use($data,$id){$lines=[];$total=0;$ids=array_column($data['items'],'product_id');if(count($ids)!==count(array_unique($ids)))throw ValidationException::withMessages(['items'=>'No repitas productos en el mismo pedido.']);foreach($data['items'] as $line){$product=Product::where('mype_id',$id)->where('active',1)->whereKey($line['product_id'])->lockForUpdate()->first();if(!$product)throw ValidationException::withMessages(['items'=>'Producto no válido para esta empresa.']);$qty=(int)$line['quantity'];if($product->stock<$qty)throw ValidationException::withMessages(['items'=>'Stock insuficiente: '.$product->name]);$price=(float)$product->sale_price;$subtotal=round($price*$qty,2);$total+=$subtotal;$lines[]=[$product,$qty,$price,$subtotal];}
 $order=Order::create(['mype_id'=>$id,'customer_id'=>$data['customer_id']??null,'code'=>'PED-'.strtoupper(\Illuminate\Support\Str::random(10)),'status'=>'pending','total'=>round($total,2),'payment_method'=>$data['payment_method']??null,'notes'=>$data['notes']??null]);foreach($lines as [$product,$qty,$price,$subtotal]){$order->items()->create(['product_id'=>$product->id,'product_name'=>$product->name,'quantity'=>$qty,'unit_price'=>$price,'subtotal'=>$subtotal]);$product->decrement('stock',$qty);}});return redirect()->route('orders.index')->with('success','Pedido creado y stock actualizado.');}
 public function update(Request $request,Order $order){abort_unless((int)$order->mype_id===$this->mid(),404);$data=$request->validate(['status'=>['required',Rule::in(['pending','completed','cancelled'])]]);DB::transaction(function()use($order,$data){$order=Order::whereKey($order->id)->lockForUpdate()->firstOrFail();$next=$data['status'];if($order->status==='cancelled'&&$next!=='cancelled')throw ValidationException::withMessages(['status'=>'No se puede reabrir un pedido cancelado.']);if($order->status==='completed'&&$next==='pending')throw ValidationException::withMessages(['status'=>'No se puede regresar un pedido completado a pendiente.']);if($next==='cancelled'&&$order->status!=='cancelled'){foreach($order->items as $item){if($item->product_id){Product::where('mype_id',$order->mype_id)->whereKey($item->product_id)->increment('stock',$item->quantity);}}}$order->update(['status'=>$next]);});return back()->with('success','Estado del pedido actualizado.');}
}
